<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('assessor');$user=current_user();require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$assessorId=(int)($user['id']??$user['user_id']??0);$attemptId=(int)($_GET['id']??0);if($assessorId<=0||$attemptId<=0){http_response_code(400);exit('Invalid request.');}$s=$conn->prepare('SELECT id,outcome_id FROM assessment_attempts WHERE id=? AND assessor_id=?');$s->bind_param('ii',$attemptId,$assessorId);$s->execute();$attempt=$s->get_result()->fetch_assoc();$s->close();if(!$attempt){http_response_code(403);exit('Assessment not found or access denied.');}$s=$conn->prepare('SELECT COUNT(*) total FROM assessment_criteria WHERE outcome_id=? AND is_active=1');$s->bind_param('i',$attempt['outcome_id']);$s->execute();$total=(int)($s->get_result()->fetch_assoc()['total']??0);$s->close();$s=$conn->prepare("SELECT COUNT(*) assessed,SUM(result='competent') competent FROM assessment_decisions WHERE attempt_id=? AND assessor_id=?");$s->bind_param('ii',$attemptId,$assessorId);$s->execute();$c=$s->get_result()->fetch_assoc()?:[];$s->close();if($total<=0||(int)$c['assessed']!==$total){as_flash('danger','Every active criterion must have a decision before submission for moderation.');header('Location: '.url('assessor/review_assessment.php?id='.$attemptId));exit;}$result=(int)$c['competent']===$total?'competent':'not_yet_competent';$s=$conn->prepare("UPDATE assessment_attempts SET assessor_result=?,status='awaiting_moderation',moderation_status='pending',assessed_at=NOW() WHERE id=? AND assessor_id=?");$s->bind_param('sii',$result,$attemptId,$assessorId);$s->execute();$s->close();as_activity($conn,$assessorId,'assessment_submitted_for_moderation','Completed all criterion decisions and submitted the assessment for moderation.','assessment_attempt',$attemptId);as_flash('success','Assessment submitted for moderation. Participant progress will update only after final approval.');header('Location: '.url('assessor/review_assessment.php?id='.$attemptId));exit;
